// ==UserScript==
// @name         Dejunk Linkedin
// @namespace    https://github.com/smkapilgupta/siteBlocker2
// @version      1.0.0
// @description  Script to block feed on Linkedin
// @author       Kapil Gupta <smkapilgupta@gmail.com>
// @match        *://*.linkedin.com/feed/*
// @run-at       document-start
// @grant        window.onurlchange
// @grant        GM_addStyle
// @grant        GM_setValue
// @grant        GM_getValue
// @updateURL    https://raw.githubusercontent.com/smkapilgupta/siteBlocker2/main/dejunkLinkedin.user.js?v=1
// @downloadURL  https://raw.githubusercontent.com/smkapilgupta/siteBlocker2/main/dejunkLinkedin.user.js?v=1
// @icon         data:image/png;base64,
// ==/UserScript==



function obliterateNode(node){
  if(!node)
    return
  while (node.firstChild) {
    node.removeChild(node.firstChild);
  }
  node.remove();
}

function udpateRecords(records){
  document.querySelectorAll("div").forEach(node=>{
    if (node.getAttribute("data-testid") === "mainFeed")
      setTimeout(()=>obliterateNode(node),0)
  })
}

const mutationObserver=new MutationObserver(udpateRecords)
mutationObserver.observe(document, {attributes: true, childList: true, subtree: true});
